def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    threes = [tuple(p) for p in np.argwhere(g == 3)]
    # cluster 3s with Chebyshev distance <= 2
    groups, seen = [], set()
    for p in threes:
        if p in seen: continue
        stack, grp = [p], []
        seen.add(p)
        while stack:
            c = stack.pop(); grp.append(c)
            for q in threes:
                if q not in seen and max(abs(q[0]-c[0]), abs(q[1]-c[1])) <= 2:
                    seen.add(q); stack.append(q)
        groups.append(grp)
    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    for grp in groups:
        if len(grp) < 2: continue
        best = None
        for a in grp:
            for dy, dx in dirs:
                ok, ext = True, 0
                for c in grp:
                    if c == a: continue
                    ry, rx = c[0]-a[0], c[1]-a[1]
                    along = ry*dy + rx*dx
                    perp = ry*dx + rx*dy if dy == 0 else rx
                    if dy == 0: perp = ry
                    if along <= 0 or abs(perp) != along:
                        ok = False; break
                    ext = max(ext, along)
                if ok and ext > 0:
                    best = (a, dy, dx, ext); break
            if best: break
        if not best: continue
        a, dy, dx, ext = best
        for d in range(1, ext+1):
            for s in range(-d, d+1):
                if dy != 0:
                    y, x = a[0]+dy*d, a[1]+s
                else:
                    y, x = a[0]+s, a[1]+dx*d
                if 0 <= y < H and 0 <= x < W and g[y, x] != 3:
                    out[y, x] = 8
        emit(out, f"Filled the cone of the V with apex {a} opening in direction {(dy,dx)} up to distance {ext} with 8, keeping the 3s.")
    emit(out, "All V-shaped cones of 3s are filled with 8.")
    return out
